#!/usr/bin/env Rscript
source(file.path(dirname(normalizePath(sub("^--file=", "", commandArgs(FALSE)[grep("^--file=", commandArgs(FALSE))]))), "dv_shared.R"))
dv_require(c("limma","statmod","digest")); hash <- dv_assert_candidate_hash(); stage <- "D04_dose_trajectory"; outdir <- dv_stage_dir(stage)
meta <- dv_assignment("Discovery"); ef <- file.path(dv_stage_dir("D01_discovery_eligibility"),"D01_discovery_eligible_expression.csv.gz"); expr <- dv_read_expression(ef,meta$UniqueSampleID,TRUE)
lock <- dv_read_csv(file.path(dv_stage_dir("D03_candidate_lock"),"D03_locked_candidates.csv"),"PG.ProteinGroups"); expr <- expr[match(lock$PG.ProteinGroups,rownames(expr)),,drop=FALSE]
d <- dv_design(meta); r <- dv_fit(expr,d,dv_three_contrasts(d),family_n=nrow(expr)); means <- do.call(rbind,lapply(seq_len(nrow(expr)),function(i)data.frame(PG.ProteinGroups=rownames(expr)[i],Dose=DV_DOSE,Modeled_mean=vapply(DV_DOSE,function(g)mean(expr[i,meta$TREAT1_clean==g],na.rm=TRUE),numeric(1)),N_observed=vapply(DV_DOSE,function(g)sum(is.finite(expr[i,meta$TREAT1_clean==g])),integer(1)))))
wide <- reshape(r[c("PG.ProteinGroups","Contrast","log2FC")],idvar="PG.ProteinGroups",timevar="Contrast",direction="wide")
tol <- .05; a<-wide$log2FC.Short_vs_Control; b<-wide$log2FC.Long_vs_Short
wide$Trajectory <- ifelse(abs(a)<=tol&abs(b)<=tol,"Flat_or_uncertain",ifelse(a>tol&b>tol,"Progressive_increase",ifelse(a< -tol&b< -tol,"Progressive_decrease",ifelse(a>tol&b< -tol&abs(a+b)<=tol,"Transient_short_peak",ifelse(a< -tol&b>tol&abs(a+b)<=tol,"Transient_short_trough",ifelse(a>tol&b< -tol,"Reversal_after_short_increase",ifelse(a< -tol&b>tol,"Reversal_after_short_decrease",ifelse(abs(a)<=tol&b>tol,"Delayed_increase",ifelse(abs(a)<=tol&b< -tol,"Delayed_decrease","Mixed_or_uncertain")))))))))
paths <- file.path(outdir,c("D04_candidate_contrasts.csv","D04_modeled_abundance_by_dose.csv","D04_trajectory_classification.csv","D04_manifest.csv")); dv_no_overwrite(paths); dv_write(dv_add_annotation(r),paths[1]);dv_write(means,paths[2]);dv_write(wide,paths[3]);dv_write(dv_manifest(stage,c(ef,file.path(dv_stage_dir("D03_candidate_lock"),"D03_locked_candidates.csv")),paths[1:3],list(candidate_hash=hash,tolerance_log2=tol)),paths[4])
